export const biomePresets = {
  canyon: {
    heightRange: [40, 220],
    fogDensity: 0.15,
    ambientTrack: "canyon_wind",
    hazards: ["rockfall", "narrow_ledge"],
  },
  ruins: {
    heightRange: [10, 60],
    fogDensity: 0.35,
    ambientTrack: "ruins_drip",
    hazards: ["collapsed_floor", "trap_pressure_plate"],
  },
  forest: {
    heightRange: [0, 80],
    fogDensity: 0.2,
    ambientTrack: "forest_birds",
    hazards: ["dense_undergrowth"],
  },
  // New: swamp biome, added for the bog-crossing level concept.
  // Lower visibility and slower footing than the other ground biomes.
  swamp: {
    heightRange: [-10, 30],
    fogDensity: 0.55,
    ambientTrack: "swamp_insects",
    hazards: ["quicksand", "collapsing_bridge", "low_visibility"],
  },
}

import { biomePresets } from "../config/biomes.presets.js"

test("swamp biome preset is valid", () => {
  expect(biomePresets.swamp.fogDensity).toBeGreaterThan(0)
})

